/* QCM — Formation EBIOS Risk Manager, préparation à l'attestation (seuil 80 %)
   Sources : guide officiel ANSSI-PA-048 « EBIOS Risk Manager — la méthode » (v1.5),
   kit de formation officiel de l'ANSSI (Support de Formation, 205 diapositives ;
   Support du Stagiaire ; Correction de l'étude de cas), et les transcriptions de la
   séance du 15 septembre.
   Chapitres calqués sur le référentiel de compétences du Club EBIOS.
   Format : {id, ch, d (1-3), q, o[], a[index corrects], e} — une seule bonne réponse. */

window.QCM_CHAPTERS = {
  1:  "Les fondamentaux du risque",
  2:  "Les 5 fondements de la méthode",
  3:  "Carte d'identité : périmètre et pyramide",
  4:  "Atelier 1 — Cadrage et socle de sécurité",
  5:  "Atelier 2 — Sources de risque",
  6:  "Atelier 3 — Scénarios stratégiques",
  7:  "Atelier 4 — Scénarios opérationnels",
  8:  "Atelier 5 — Traitement du risque",
  9:  "Entrées, sorties et participants",
  10: "Vocabulaire et pièges",
  11: "Le contexte de la méthode",
  12: "Le support : commandements, Flash, risque IA",
  13: "Les cas pratiques du support"
};

window.QCM_DATA = [

/* ---- Ch. 1 : les fondamentaux du risque ---- */
{id:"E01", ch:1, d:1, q:"Quelle est la différence entre un <b>danger</b> et un <b>risque</b>&nbsp;?", o:["Le danger est une propriété intrinsèque ; le risque est une situation d'exposition à ce danger","Le danger est avéré, le risque est potentiel","Le danger est technique, le risque est métier","Le danger vient de l'extérieur, le risque de l'intérieur"], a:[0], e:"La plaque de verglas est le <b>danger</b> — un fait physique. Tant que personne ne passe, il n'y a <b>aucun risque</b>. La fracture est le <b>dommage</b>. Le risque n'est donc <b>pas une propriété du système</b>&nbsp;: c'est une situation."},
{id:"E02", ch:1, d:1, q:"De quoi le niveau d'un risque est-il fonction&nbsp;?", o:["De sa gravité et de sa vraisemblance","De sa probabilité et de son coût de traitement","De sa fréquence et de sa durée","De son impact et du nombre d'actifs touchés"], a:[0], e:"Le risque se lit dans un <b>espace cartésien à deux dimensions</b>. La <b>gravité</b> est déterminée à l'<b>atelier 1</b> (événements redoutés), la <b>vraisemblance</b> à l'<b>atelier 4</b> (scénarios opérationnels). Le croisement des deux donne la matrice des risques de l'atelier 5."},
{id:"E03", ch:1, d:2, q:"Comment se décompose la <b>vraisemblance</b>&nbsp;?", o:["Menace × Vulnérabilité","Gravité × Exposition","Impact × Fréquence","Attractivité × Gravité"], a:[0], e:"Et au second niveau&nbsp;: la <b>menace</b> = <b>attractivité de la cible</b> + <b>vecteur d'accès</b>&nbsp;; la <b>vulnérabilité</b> = <b>vulnérabilités intrinsèques</b> (CVE, obsolescence, défauts de configuration) + <b>complexité de l'attaque</b>, c'est-à-dire la longueur de la chaîne à parcourir."},
{id:"E04", ch:1, d:2, q:"Pourquoi les échelles de cotation comptent-elles généralement <b>4 niveaux</b>&nbsp;?", o:["Pour éliminer le biais du juste milieu : une échelle paire force à trancher","Parce que la norme ISO 27005 l'impose","Parce que quatre niveaux suffisent à couvrir tous les cas","Pour aligner l'échelle sur les quatre critères DICP"], a:[0], e:"Avec une échelle impaire, les participants choisissent massivement la valeur <b>centrale</b> «&nbsp;pour ne pas se mouiller&nbsp;». Une échelle paire oblige à décider&nbsp;: plutôt mineur (1-2), plutôt majeur (3-4)."},
{id:"E05", ch:1, d:2, q:"Quelles propriétés une bonne échelle d'évaluation doit-elle avoir&nbsp;?", o:["Non ambiguë, explicite, comprise par tous, adaptée à l'organisme, graduée de façon cohérente","Normalisée, certifiée, auditable, reproductible, universelle","Numérique, linéaire, bornée, symétrique, documentée","Confidentielle, validée par la direction, révisée chaque année"], a:[0], e:"La propriété la plus souvent oubliée est «&nbsp;<b>comprise par tous</b>&nbsp;»&nbsp;: l'échelle doit rester intelligible pour un directeur financier ou un juriste, pas seulement pour un technicien. Et «&nbsp;<b>adaptée à l'organisme</b>&nbsp;»&nbsp;: 50 000 € est critique pour une TPE, insignifiant pour un grand groupe."},
{id:"E06", ch:1, d:2, q:"La <b>capacité</b> et la <b>motivation</b> d'une source de risque relèvent de…", o:["la vraisemblance","la gravité","les deux à parts égales","du cadrage, pas de la cotation"], a:[0], e:"La règle mémotechnique&nbsp;: ce qui regarde <b>vers l'intérieur</b> de l'organisation — valeurs métier, préjudices, réputation, survie — relève de la <b>gravité</b>&nbsp;; ce qui regarde <b>vers l'extérieur et la technique</b> — attaquant, motivation, vecteur, failles, complexité — relève de la <b>vraisemblance</b>."},
{id:"E07", ch:1, d:2, q:"Combien de besoins de sécurité un <b>événement redouté</b> concerne-t-il&nbsp;?", o:["Un seul à la fois — un même incident produit donc plusieurs événements redoutés","Tous ceux qui sont affectés par l'incident","Deux au maximum","Autant que nécessaire, sans règle"], a:[0], e:"Sur une borne Wi-Fi&nbsp;: la <b>destruction</b> atteint la <b>disponibilité</b>, l'<b>écoute passive</b> la <b>confidentialité</b>, l'<b>altération des paquets</b> l'<b>intégrité</b> — trois événements redoutés distincts. Les critères sont notés <b>DICP</b>&nbsp;: disponibilité, intégrité, confidentialité, preuve."},
{id:"E08", ch:1, d:3, q:"Quelle différence y a-t-il entre la <b>sécurité</b> (<i>security</i>) et la <b>sûreté</b> (<i>safety</i>), et quelle conséquence pour EBIOS RM&nbsp;?", o:["La sécurité traite l'intentionnel malveillant, la sûreté l'accidentel — et EBIOS RM ne traite que la sécurité","La sécurité traite le logique, la sûreté le physique — EBIOS RM traite les deux","La sécurité est réglementaire, la sûreté est normative — EBIOS RM traite la sûreté","Il n'y a pas de différence en français, seulement en anglais"], a:[0], e:"Pour les aléas de sûreté industrielle, il faut coupler EBIOS RM avec des méthodes comme l'<b>AMDEC</b> ou le <b>Cyber-PHA</b> (CEI 62443). C'est la conséquence méthodologique qui compte, pas seulement la définition."},
{id:"E09", ch:1, d:2, q:"Quelle est la <b>norme mère</b> de la gestion des risques&nbsp;?", o:["L'ISO 31000 — l'ISO 27005 n'en est que la déclinaison pour la sécurité de l'information","L'ISO 27005, dont l'ISO 31000 est un guide d'application","L'ISO 27001, qui couvre le management des risques","L'ISO 9001, socle de toutes les normes de management"], a:[0], e:"L'ISO 31000 s'applique à tous les secteurs&nbsp;: risque financier, industriel, médical. EBIOS RM, elle, est une <b>méthode</b> qui instancie l'ISO 27005 — laquelle décline l'ISO 31000."},
{id:"E10", ch:1, d:3, q:"Que recouvre l'<b>appréciation du risque</b> au sens de l'ISO 27005&nbsp;?", o:["Le terme englobant : identification, puis estimation, puis évaluation","Le seul calcul gravité × vraisemblance","La seule confrontation aux critères d'acceptation","La phase qui suit le traitement du risque"], a:[0], e:"<b>Évaluer</b> le risque, c'est précisément le <b>confronter aux critères d'acceptation</b> de l'organisation et trancher. Les quatre phases du processus ISO 27005&nbsp;: établissement du contexte, appréciation, traitement, acceptation du risque résiduel."},

/* ---- Ch. 2 : les 5 fondements ---- */
{id:"E11", ch:2, d:1, q:"Quel est le <b>fondement 1</b> de la méthode EBIOS Risk Manager&nbsp;?", o:["Une démarche structurée en ateliers","Une approche exhaustive des menaces","Une cotation quantitative du risque","Une conformité aux normes ISO 27000"], a:[0], e:"Les cinq fondements, à savoir lister — c'est une compétence explicitement exigée par le support de formation officiel&nbsp;: <b>(1)</b> une démarche structurée en <b>ateliers</b> · <b>(2)</b> une <b>synthèse entre conformité et scénarios</b> · <b>(3)</b> une <b>alternance entre points de vue</b> · <b>(4)</b> une prise en compte de l'<b>écosystème</b> · <b>(5)</b> une approche <b>efficace plutôt qu'exhaustive</b>."},
{id:"E12", ch:2, d:2, q:"Que signifie le <b>fondement 2</b>, «&nbsp;une synthèse entre conformité et scénarios de risques&nbsp;»&nbsp;?", o:["La conformité traite les risques communs et accidentels via le socle ; les scénarios traitent les attaques ciblées et sophistiquées","La conformité s'applique aux grandes entreprises, les scénarios aux PME","La conformité est obligatoire, les scénarios sont facultatifs","La conformité relève de l'atelier 5, les scénarios de l'atelier 1"], a:[0], e:"C'est la traduction de la <b>pyramide du management du risque numérique</b>&nbsp;: on ne traite pas une attaque étatique avec une liste de contrôle, ni une clé USB perdue avec un graphe d'attaque. Chaque approche est placée «&nbsp;là où elle apporte la plus forte valeur ajoutée&nbsp;»."},
{id:"E13", ch:2, d:2, q:"Que décrit le <b>fondement 3</b>, «&nbsp;une alternance entre points de vue&nbsp;»&nbsp;?", o:["L'alternance entre le point de vue de l'organisation et celui de l'attaquant au fil des ateliers","L'alternance entre la vue métier et la vue technique d'un même actif","L'alternance entre l'analyse qualitative et l'analyse quantitative","L'alternance entre les ateliers collectifs et le travail individuel"], a:[0], e:"Le support officiel le schématise en trois colonnes&nbsp;: <b>organisation → attaquant → organisation</b>. On part de ce que l'on protège, on passe du côté de celui qui attaque, puis on revient décider. C'est ce qui donne son rythme à l'enchaînement des cinq ateliers."},
{id:"E14", ch:2, d:1, q:"Que dit le <b>fondement 5</b>&nbsp;?", o:["Une approche efficace plutôt qu'exhaustive : se focaliser sur les éléments les plus importants et produire un document accessible","Une approche exhaustive, seule garantie de ne rien oublier","Une approche quantitative, seule opposable à un auditeur","Une approche annuelle, alignée sur le cycle budgétaire"], a:[0], e:"«&nbsp;EBIOS RM est un <b>outil de gestion de risque</b> efficace et utile&nbsp;» — pas un inventaire. C'est précisément ce qui l'oppose à <b>EBIOS 2010</b>, qui visait l'<b>exhaustivité</b>."},
{id:"E15", ch:2, d:2, q:"Pourquoi le <b>fondement 4</b> insiste-t-il sur l'écosystème&nbsp;?", o:["Parce que de plus en plus de modes opératoires exploitent les maillons les plus vulnérables de l'écosystème pour atteindre leur objectif","Parce que le RGPD impose d'auditer ses sous-traitants","Parce que l'écosystème représente la majorité du budget de sécurité","Parce que les parties prenantes financent l'analyse de risque"], a:[0], e:"Les exemples du guide&nbsp;: atteindre la disponibilité d'un service en attaquant le <b>fournisseur de service en nuage</b>, ou piéger la <b>chaîne logistique</b> d'approvisionnement de serveurs. C'est tout l'objet de l'<b>atelier 3</b>."},
{id:"E16", ch:2, d:3, q:"Quelles sont les deux compétences que le support de formation exige à l'issue du module «&nbsp;les bases&nbsp;»&nbsp;?", o:["Savoir définir un risque, et lister les 5 fondamentaux de la méthode","Savoir coter la gravité, et construire une matrice de risque","Savoir animer un atelier, et rédiger un plan de traitement","Savoir utiliser Agile Risk Manager, et exporter un rapport"], a:[0], e:"C'est la diapositive «&nbsp;<b>ce que vous devez être capable de faire à ce stade</b>&nbsp;» du support officiel. Deux compétences seulement, mais elles conditionnent tout le reste — et la seconde est une <b>question de restitution pure</b>."},

/* ---- Ch. 3 : carte d'identité ---- */
{id:"E17", ch:3, d:1, q:"Qui publie la méthode EBIOS Risk Manager, et avec quel appui&nbsp;?", o:["L'ANSSI, avec le soutien du Club EBIOS","Le Club EBIOS seul, association loi 1901","L'ISO, sous la référence 27005","Le CLUSIF, qui publie aussi MEHARI"], a:[0], e:"Le <b>Club EBIOS</b> est une association loi 1901 qui enrichit le référentiel français. C'est aussi lui qui agrée les organismes certificateurs de compétences, tandis que l'<b>ANSSI</b> labellise les <b>outils</b> logiciels."},
{id:"E18", ch:3, d:2, q:"Que représentent les trois étages de la <b>pyramide du management du risque numérique</b>&nbsp;?", o:["Base : hygiène et principes de base · milieu : cadre réglementaire et normatif · sommet : appréciation des risques par scénarios","Base : technique · milieu : organisationnel · sommet : stratégique","Base : atelier 1 · milieu : ateliers 2 à 4 · sommet : atelier 5","Base : prévention · milieu : détection · sommet : réaction"], a:[0], e:"Les <b>étages 1 et 2</b> forment le <b>socle de sécurité</b>, traité par <b>conformité</b> à l'atelier 1. EBIOS RM concentre son effort sur le <b>sommet</b> — les attaques ciblées — là où une liste de contrôle ne suffit plus."},
{id:"E19", ch:3, d:2, q:"EBIOS RM est-elle adaptée à une association de dix salariés&nbsp;?", o:["Non : c'est un outil surdimensionné. Il faut lui préférer le guide d'hygiène de l'ANSSI ou une démarche ISO 27005 simplifiée","Oui, en se limitant aux ateliers 1 et 5","Oui, c'est sa cible principale depuis 2018","Non, uniquement à cause du coût des outils labellisés"], a:[0], e:"EBIOS RM vise les <b>grandes entreprises, les OIV et les systèmes critiques</b>. Pour une petite structure, le besoin réel se situe aux <b>étages 1 et 2</b> de la pyramide — que la méthode considère justement comme un <b>prérequis</b>."},
{id:"E20", ch:3, d:2, q:"Quelle est la différence entre un <b>audit de sécurité</b> et une <b>analyse de risque</b>&nbsp;?", o:["L'audit exige un référentiel préexistant ; l'analyse de risque peut partir de zéro","L'audit est externe, l'analyse de risque est interne","L'audit est technique, l'analyse de risque est organisationnelle","L'audit est ponctuel, l'analyse de risque est continue"], a:[0], e:"L'audit est un travail de <b>conformité</b>&nbsp;: on compare la réalité à un document. Sans référentiel, l'auditeur <b>ne peut pas travailler</b>. L'analyse de risque est un travail d'<b>investigation</b>&nbsp;: elle reconstitue le panorama par ateliers avec les métiers."},
{id:"E21", ch:3, d:3, q:"Que garantit la <b>labellisation d'un outil</b> par l'ANSSI&nbsp;?", o:["Que l'outil implémente fidèlement les 5 ateliers et permet la conformité à l'ISO 27005","Que l'éditeur est certifié ISO 27001","Que l'outil est hébergé en France","Que les analyses produites sont opposables juridiquement"], a:[0], e:"Attention à ne pas confondre les <b>quatre dispositifs</b> du Club EBIOS&nbsp;: les <b>formateurs signataires</b> de la charte, les <b>formations labellisées</b> SecNumedu-FC, la <b>certification de compétences</b> délivrée par des organismes accrédités, et les <b>logiciels labellisés</b> par l'ANSSI."},
{id:"E22", ch:3, d:2, q:"Qu'est-ce qui oppose <b>EBIOS 2010</b> et <b>EBIOS Risk Manager</b> sur la philosophie&nbsp;?", o:["EBIOS 2010 vise l'exhaustivité, EBIOS RM la représentativité","EBIOS 2010 vise la représentativité, EBIOS RM l'exhaustivité","Les deux visent l'exhaustivité, sur des périmètres différents","Les deux visent la représentativité, avec des échelles différentes"], a:[0], e:"Les autres oppositions&nbsp;: centre de gravité <b>SI</b> contre <b>métier</b> · menaces <b>unitaires</b> contre <b>scénarisées</b> · démarche <b>ascendante</b> contre <b>descendante</b> · <b>5 modules</b> rigides contre <b>5 ateliers</b> agiles · l'<b>accidentel</b> traité contre l'<b>accidentel renvoyé au socle</b>."},
{id:"E23", ch:3, d:3, q:"Peut-on revenir sur un atelier déjà terminé&nbsp;?", o:["Oui : la démarche est itérative — découvrir un sous-traitant oublié à l'atelier 3 autorise à modifier l'atelier 1","Non : les ateliers sont séquentiels et verrouillés une fois validés","Oui, mais uniquement entre les ateliers 4 et 5","Uniquement avec l'accord écrit de la direction"], a:[0], e:"C'est ce qui distingue une démarche <b>agile</b> d'un tunnel. EBIOS RM n'est «&nbsp;pas un tunnel figé&nbsp;»&nbsp;: les livrables précédents s'ajustent au fur et à mesure des découvertes."},

/* ---- Ch. 4 : atelier 1 ---- */
{id:"E24", ch:4, d:1, q:"Quel est l'<b>objectif</b> de l'atelier 1&nbsp;?", o:["Définir le cadre de l'étude et du projet, son périmètre métier et technique","Identifier les sources de risque et leurs objectifs visés","Cartographier l'écosystème et ses parties prenantes","Construire les modes opératoires techniques"], a:[0], e:"L'atelier 1 produit aussi les <b>événements redoutés</b> avec leur <b>gravité</b>, et le <b>socle de sécurité</b>. C'est l'atelier le plus long&nbsp;: il peut prendre deux jours complets."},
{id:"E25", ch:4, d:2, q:"Quelles sont les <b>quatre activités</b> de l'atelier 1&nbsp;?", o:["Définir le cadre de l'étude · définir le périmètre métier et technique · identifier les événements redoutés · déterminer le socle de sécurité","Cadrer · coter · arbitrer · valider","Identifier les actifs · les menaces · les vulnérabilités · les mesures","Réunir les participants · collecter · analyser · restituer"], a:[0], e:"Numérotées <b>1-1</b> à <b>1-4</b> dans le support officiel. L'activité <b>1-4</b>, le socle de sécurité, est celle qu'on oublie le plus souvent — or elle conditionne tout le reste&nbsp;: sans état des lieux de l'existant, on préconise des mesures déjà en place."},
{id:"E26", ch:4, d:2, q:"Quelle est la distinction entre <b>valeur métier</b> et <b>bien support</b>&nbsp;?", o:["La valeur métier est ce qu'on cherche à protéger (processus, information) ; le bien support est ce sur quoi elle repose (serveur, logiciel, local, personne)","La valeur métier est immatérielle, le bien support est matériel","La valeur métier appartient au métier, le bien support à la DSI","La valeur métier est cotée en gravité, le bien support en vraisemblance"], a:[0], e:"Un bien support peut être <b>numérique, physique ou organisationnel</b> — y compris une <b>personne</b>. La valeur métier, elle, peut être un processus, une fonction support, une étape de projet ou une information."},
{id:"E27", ch:4, d:1, q:"Que signifie le niveau de gravité <b>G4</b>&nbsp;?", o:["Critique : l'organisme ne surmontera vraisemblablement pas la situation — sa survie est menacée","Grave : l'organisme surmontera avec de sérieuses difficultés","Significative : mode dégradé temporaire","Majeure : pertes financières supérieures à 10 % du chiffre d'affaires"], a:[0], e:"Les repères&nbsp;: la ligne entre <b>G2 et G3</b> est celle de l'<b>impact sur la sécurité des personnes</b>&nbsp;; la ligne entre <b>G3 et G4</b> est celle de la <b>survie de l'organisation</b>. On ne place en G4 que si la survie est réellement en jeu."},
{id:"E28", ch:4, d:2, q:"Que contient le <b>socle de sécurité</b>&nbsp;?", o:["La liste des référentiels applicables, leur état d'application, et l'identification des écarts avec leur justification","La liste des mesures à déployer après l'analyse","L'inventaire exhaustif des biens supports","Les scénarios de risque jugés acceptables"], a:[0], e:"Les <b>écarts</b> sont le livrable le plus important&nbsp;: ils alimentent les ateliers suivants. Un socle déclaré parfait vide l'analyse de sa substance — c'est d'ailleurs pourquoi l'énoncé du devoir demande de «&nbsp;laisser suffisamment de faiblesses&nbsp;»."},
{id:"E29", ch:4, d:3, q:"Lequel de ces référentiels <b>n'entre pas</b> dans le socle de sécurité&nbsp;?", o:["L'IGI 1300 — protection du secret de la défense nationale","La PSSI de l'organisation","Le guide d'hygiène informatique de l'ANSSI","L'annexe A de l'ISO/IEC 27001"], a:[0], e:"L'IGI 1300 s'impose aux <b>personnes physiques accréditées</b> et aux <b>locaux classifiés</b>, non au système d'information bureautique. Le critère de tri&nbsp;: le socle rassemble les référentiels <b>applicables au SI</b>. Le RGPD, la LPM pour un OIV et le code de la santé publique pour un hôpital en font partie."},
{id:"E30", ch:4, d:2, q:"Pourquoi faut-il <b>limiter</b> le nombre de valeurs métier et de biens supports&nbsp;?", o:["Parce que la méthode vise l'efficacité plutôt que l'exhaustivité : au-delà, l'étude devient ingérable et perd son sens","Parce que l'outil Agile Risk Manager plafonne à dix entrées","Parce que la direction n'accepte pas plus de dix pages","Parce que l'ISO 27005 fixe un maximum réglementaire"], a:[0], e:"C'est l'application directe du <b>fondement 5</b>. Le support officiel consacre une diapositive entière à cette question&nbsp;: «&nbsp;pourquoi et comment limiter le nombre de valeurs métier et de biens supports&nbsp;?&nbsp;»"},
{id:"E31", ch:4, d:2, q:"Comment un <b>événement redouté</b> doit-il être formulé&nbsp;?", o:["Sous une forme courte et compréhensible par le métier, traduisant sa crainte — sans chercher l'exhaustivité","Sous forme d'une CVE ou d'une référence technique","Sous forme d'un scénario d'attaque détaillé étape par étape","Sous forme d'une mesure de sécurité manquante"], a:[0], e:"«&nbsp;Les événements redoutés doivent conserver du <b>sens pour le métier</b>.&nbsp;» C'est le métier qui les exprime&nbsp;: le rôle de l'analyste est de <b>canaliser</b> cette parole, pas de la traduire en jargon technique."},

/* ---- Ch. 5 : atelier 2 ---- */
{id:"E32", ch:5, d:1, q:"Quel est l'objectif de l'<b>atelier 2</b>&nbsp;?", o:["Identifier les sources de risque (SR) et leurs objectifs visés (OV) en lien avec l'objet de l'étude","Cartographier les parties prenantes de l'écosystème","Coter la vraisemblance des chemins d'attaque","Définir la stratégie de traitement du risque"], a:[0], e:"La question de l'atelier, formulée telle quelle par le guide&nbsp;: «&nbsp;<b>qui ou quoi</b> pourrait porter atteinte aux missions et valeurs métier identifiées dans l'atelier 1, et <b>dans quels buts</b>&nbsp;?&nbsp;»"},
{id:"E33", ch:5, d:2, q:"Que produit l'atelier 2&nbsp;?", o:["La liste des couples SR/OV retenus, celle des couples secondaires à mettre sous surveillance, et une cartographie","La liste des scénarios stratégiques","La cartographie de menace de l'écosystème","Le plan de traitement du risque"], a:[0], e:"Les couples <b>secondaires</b> ne sont pas jetés&nbsp;: ils sont «&nbsp;si possible mis sous surveillance&nbsp;». C'est une nuance souvent oubliée — l'atelier 2 ne produit pas une seule liste mais <b>deux</b>, plus une représentation."},
{id:"E34", ch:5, d:2, q:"Qu'est-ce qu'un <b>couple SR/OV</b>&nbsp;?", o:["L'association d'une source de risque et de l'objectif qu'elle vise — la même source peut viser plusieurs objectifs","L'association d'une source de risque et d'une vulnérabilité","L'association d'un scénario de risque et d'une valeur métier","L'association d'une source de risque et d'un objectif de sécurité"], a:[0], e:"C'est le couple, et non la source seule, qui est retenu et évalué. Un même cybercriminel peut viser l'<b>extorsion</b> ou la <b>revente de données</b>&nbsp;: ce sont deux couples distincts, avec une pertinence différente."},
{id:"E35", ch:5, d:2, q:"Qui participe à l'atelier 2&nbsp;?", o:["Métiers, RSSI, éventuellement un spécialiste de l'analyse de la menace, et la direction pour valider","La DSI et les architectes SI uniquement","La direction seule","Les juristes et le service achats"], a:[0], e:"La direction intervient <b>au minimum lors de la dernière étape</b>&nbsp;: elle valide les couples retenus. Le <b>spécialiste de l'analyse de la menace numérique</b> — la CTI — est facultatif mais fortement utile pour calibrer la pertinence des sources."},
{id:"E36", ch:5, d:3, q:"Sur quels critères évalue-t-on la pertinence d'un couple SR/OV&nbsp;?", o:["La motivation de la source, ses ressources, et son activité — croisées avec l'objet de l'étude","Sa probabilité statistique, calculée sur les incidents passés","Le coût des mesures nécessaires pour s'en protéger","Le nombre de biens supports concernés"], a:[0], e:"On retient les couples les plus <b>pertinents</b>, pas les plus nombreux&nbsp;: c'est encore le <b>fondement 5</b>. Les critères portent sur la <b>source</b> — ce qu'elle veut, ce qu'elle peut, ce qu'elle fait déjà."},

/* ---- Ch. 6 : atelier 3 ---- */
{id:"E37", ch:6, d:1, q:"Quel est l'objectif de l'<b>atelier 3</b>&nbsp;?", o:["Identifier les parties prenantes critiques de l'écosystème et construire des scénarios de risque de haut niveau","Construire les modes opératoires techniques détaillés","Déterminer le socle de sécurité","Évaluer la vraisemblance des scénarios"], a:[0], e:"Le guide précise qu'il est «&nbsp;à aborder comme une <b>étude préliminaire de risque</b>&nbsp;». Les scénarios stratégiques sont «&nbsp;autant de <b>chemins d'attaque</b> que pourrait emprunter une source de risque pour atteindre son objectif&nbsp;»."},
{id:"E38", ch:6, d:2, q:"Que produit l'atelier 3&nbsp;?", o:["Une cartographie de menace de l'écosystème, les scénarios stratégiques, et les mesures de sécurité retenues pour l'écosystème","Les seuls scénarios stratégiques","La liste des couples SR/OV","Les scénarios opérationnels et leur vraisemblance"], a:[0], e:"Le troisième livrable est le plus souvent oublié&nbsp;: l'atelier 3 produit <b>déjà des mesures</b> — celles qui portent sur l'<b>écosystème</b>, c'est-à-dire sur les parties prenantes. Elles seront reprises en entrée de l'atelier 5."},
{id:"E39", ch:6, d:2, q:"Qui participe à l'atelier 3, en plus des métiers et du RSSI&nbsp;?", o:["Les architectes fonctionnels et les juristes — ou les acteurs qui connaissent les engagements contractuels","La DSI et les administrateurs systèmes","La direction générale seule","Les auditeurs externes"], a:[0], e:"La présence des <b>juristes</b> ou du <b>service achats</b> est logique&nbsp;: l'atelier porte sur les <b>parties prenantes</b>, donc sur les <b>contrats</b> qui les lient à l'organisation. C'est l'atelier où la sécurité rencontre le droit des contrats."},
{id:"E40", ch:6, d:3, q:"Qu'est-ce qu'une <b>partie prenante critique</b>&nbsp;?", o:["Une partie prenante dont le niveau de menace induit est jugé suffisamment élevé pour justifier des mesures spécifiques","Une partie prenante dont le contrat représente plus de 10 % du budget","Une partie prenante qui a déjà subi une compromission","Une partie prenante située hors de l'Union européenne"], a:[0], e:"La criticité se déduit de la <b>cartographie du niveau de dangerosité</b> induit par les parties prenantes majeures. Ce n'est ni une question de taille ni d'historique&nbsp;: c'est la <b>menace qu'elle fait porter</b> à l'organisation."},
{id:"E41", ch:6, d:2, q:"Pourquoi l'atelier 3 est-il dit «&nbsp;de haut niveau&nbsp;»&nbsp;?", o:["Parce qu'il décrit les chemins d'attaque sans entrer dans les modes opératoires techniques — c'est l'atelier 4 qui le fait","Parce qu'il n'implique que la direction générale","Parce qu'il porte sur les risques de niveau G4 uniquement","Parce qu'il précède la validation par l'autorité d'homologation"], a:[0], e:"Le passage du <b>stratégique</b> à l'<b>opérationnel</b> est le pivot de la méthode&nbsp;: l'atelier 3 dit <b>par où</b> l'attaquant passe (quelles parties prenantes, quelles valeurs métier), l'atelier 4 dit <b>comment</b> techniquement."},

/* ---- Ch. 7 : atelier 4 ---- */
{id:"E42", ch:7, d:1, q:"Quel est l'objectif de l'<b>atelier 4</b>&nbsp;?", o:["Construire les scénarios opérationnels schématisant les modes opératoires techniques des sources de risque","Identifier les parties prenantes critiques","Définir les échelles de gravité","Arbitrer la stratégie de traitement"], a:[0], e:"Même démarche que l'atelier 3, mais centrée sur les <b>biens supports</b> et non sur l'écosystème. La période à considérer est celle du <b>cycle opérationnel</b>."},
{id:"E43", ch:7, d:1, q:"Quelle grandeur est déterminée à l'issue de l'atelier 4&nbsp;?", o:["La vraisemblance","La gravité","Le risque résiduel","Le niveau de menace de l'écosystème"], a:[0], e:"C'est le résultat capital de cet atelier. La <b>gravité</b> vient de l'atelier 1, la <b>vraisemblance</b> de l'atelier 4&nbsp;: leur croisement donne la <b>matrice des risques</b>, exploitée à l'atelier 5."},
{id:"E44", ch:7, d:2, q:"Qui participe à l'atelier 4&nbsp;?", o:["Le RSSI, la DSI, les architectes SI, éventuellement un spécialiste cybersécurité — sans la direction ni les métiers","Les mêmes participants que l'atelier 1","La direction et les juristes","Les métiers et le service achats"], a:[0], e:"C'est le <b>seul atelier</b> où la direction et les métiers n'apparaissent pas&nbsp;: c'est l'atelier le plus <b>technique</b>. Les métiers, mobilisés aux ateliers 1 à 3, sont libérés."},
{id:"E45", ch:7, d:2, q:"Quels référentiels alimentent la construction des scénarios opérationnels&nbsp;?", o:["Les référentiels de cyber-renseignement, comme MITRE ATT&amp;CK et les catalogues CAPEC","Les annexes de l'ISO 27002","Le guide d'hygiène informatique de l'ANSSI","Les 93 mesures de l'ISO 27002:2022"], a:[0], e:"Un scénario opérationnel décrit la séquence&nbsp;: <b>reconnaissance</b>, intrusion initiale, <b>élévation de privilèges</b>, <b>mouvement latéral</b>, puis exfiltration ou chiffrement. Les référentiels d'attaque servent à ne rien inventer."},
{id:"E46", ch:7, d:2, q:"Quelles sont les deux activités de l'atelier 4&nbsp;?", o:["Élaborer les scénarios opérationnels, puis évaluer leur vraisemblance","Cartographier l'écosystème, puis élaborer les scénarios","Identifier les biens supports, puis les vulnérabilités","Coter la gravité, puis la vraisemblance"], a:[0], e:"Numérotées <b>4-1</b> et <b>4-2</b> dans le support officiel. L'atelier 4 est le plus court en nombre d'activités mais le plus dense techniquement."},

/* ---- Ch. 8 : atelier 5 ---- */
{id:"E47", ch:8, d:1, q:"Quel est l'objectif de l'<b>atelier 5</b>&nbsp;?", o:["Définir une stratégie de traitement du risque et identifier les risques résiduels","Construire les scénarios opérationnels","Cartographier les sources de risque","Définir le périmètre métier et technique"], a:[0], e:"La stratégie aboutit à des <b>mesures de sécurité</b> recensées dans un <b>plan de traitement du risque</b>. Puis les <b>risques résiduels</b> sont identifiés, ainsi que le <b>cadre de suivi</b>."},
{id:"E48", ch:8, d:2, q:"Dans quel ordre l'atelier 5 enchaîne-t-il ses travaux&nbsp;?", o:["Évaluer les risques → décider de la stratégie → définir les mesures → réévaluer les risques résiduels → mettre en place le cadre de suivi","Définir les mesures → évaluer les risques → décider de la stratégie → acter les résiduels","Décider de la stratégie → évaluer les risques → mettre en place le suivi → définir les mesures","Acter les risques résiduels → définir les mesures → évaluer les risques"], a:[0], e:"L'ordre n'est pas arbitraire&nbsp;: on ne peut <b>arbitrer</b> qu'après avoir <b>comparé</b> les risques entre eux, et on ne peut <b>réévaluer le résiduel</b> qu'après avoir <b>choisi les mesures</b>. Le <b>cadre de suivi</b> vient en dernier — c'est lui qui fait de l'analyse un cycle plutôt qu'un document mort."},
{id:"E49", ch:8, d:2, q:"Qui participe à l'atelier 5&nbsp;?", o:["Les mêmes qu'à l'atelier 1 : direction, métiers, RSSI, DSI","Le RSSI et la DSI uniquement","La direction générale seule","Les architectes et les juristes"], a:[0], e:"La boucle se referme&nbsp;: <b>ceux qui ont cadré décident du traitement</b>. C'est cohérent avec le <b>fondement 3</b> — on repasse au point de vue de l'organisation après être passé par celui de l'attaquant."},
{id:"E50", ch:8, d:2, q:"Quelles sont les quatre stratégies de traitement du risque&nbsp;?", o:["Maintien (acceptation) · refus (évitement) · réduction (mitigation) · transfert (partage)","Prévention · détection · correction · récupération","Éviter · réduire · assurer · documenter","Identifier · estimer · évaluer · accepter"], a:[0], e:"Le <b>maintien</b> exige une validation signée par la <b>direction générale</b>. Le <b>refus</b> supprime l'activité elle-même. La <b>réduction</b> est la plus fréquente. Le <b>transfert</b> passe par l'infogérance ou la cyber-assurance."},
{id:"E51", ch:8, d:2, q:"Qu'est-ce que le <b>risque résiduel</b>&nbsp;?", o:["Le niveau de risque qui subsiste après application des mesures du plan de traitement","Le risque que l'on a choisi d'ignorer","Le risque porté par les parties prenantes","Le risque non identifié lors de l'analyse"], a:[0], e:"Il doit être <b>formellement accepté</b>&nbsp;: c'est l'autorité — en principe celle qui délivre la <b>décision d'homologation</b> — qui l'assume. Un risque résiduel jugé inacceptable renvoie à une nouvelle itération."},
{id:"E52", ch:8, d:3, q:"Le support du cours parle de <b>PACS</b>, le guide ANSSI v1.5 de <b>plan de traitement du risque</b>. Qu'en conclure&nbsp;?", o:["Les deux désignent le même livrable : le vocabulaire a été mis à jour","Ce sont deux livrables distincts de l'atelier 5","Le PACS précède le plan de traitement dans le déroulé","Le PACS est le nom de l'outil, le plan de traitement celui de la méthode"], a:[0], e:"<b>PACS = plan d'amélioration continue de la sécurité = plan de traitement du risque.</b> Trois renommages sont à connaître&nbsp;: <b>PACS → plan de traitement du risque</b>, <b>entité responsable → propriétaire</b>, <b>synthèse des scénarios → évaluation des risques</b>. Le <b>cadre de suivi</b>, lui, reste un livrable distinct de l'atelier 5."},

/* ---- Ch. 9 : entrées, sorties, participants ---- */
{id:"E53", ch:9, d:2, q:"Quels éléments l'atelier 3 reçoit-il <b>en entrée</b>&nbsp;?", o:["Les missions et valeurs métier, les événements redoutés et leur gravité (atelier 1), et les couples SR/OV retenus (atelier 2)","Uniquement les couples SR/OV de l'atelier 2","Les scénarios opérationnels de l'atelier 4","Le socle de sécurité et les biens supports"], a:[0], e:"L'atelier 3 est le <b>point de convergence</b> des deux premiers&nbsp;: il croise ce qu'on protège (atelier 1) avec qui nous attaque (atelier 2), puis regarde par où l'attaque peut passer — l'écosystème."},
{id:"E54", ch:9, d:3, q:"Quels éléments l'atelier 4 reçoit-il <b>en entrée</b>&nbsp;?", o:["Missions, valeurs métier et biens supports, le socle de sécurité (atelier 1), les couples SR/OV (atelier 2) et les scénarios stratégiques (atelier 3)","Uniquement les scénarios stratégiques de l'atelier 3","Uniquement les biens supports et le socle","Les mesures de sécurité de l'écosystème"], a:[0], e:"C'est l'atelier qui reçoit le <b>plus d'entrées</b>&nbsp;: il mobilise les trois ateliers précédents. Le <b>socle de sécurité</b> y est indispensable — c'est lui qui dit quelles défenses l'attaquant devra franchir."},
{id:"E55", ch:9, d:2, q:"Quels éléments l'atelier 5 reçoit-il <b>en entrée</b>&nbsp;?", o:["Le socle (atelier 1), les mesures pour l'écosystème et les scénarios stratégiques (atelier 3), et les scénarios opérationnels (atelier 4)","Uniquement les scénarios opérationnels de l'atelier 4","Uniquement les couples SR/OV et les événements redoutés","Le plan de traitement du risque de l'itération précédente"], a:[0], e:"Noter que l'atelier 5 récupère des <b>mesures déjà identifiées</b> à l'atelier 3 — celles portant sur l'écosystème. Il ne part donc pas d'une page blanche&nbsp;: il consolide."},
{id:"E56", ch:9, d:1, q:"Dans quel atelier la <b>direction</b> n'apparaît-elle pas&nbsp;?", o:["L'atelier 4","L'atelier 1","L'atelier 3","L'atelier 5"], a:[0], e:"L'atelier 4 est le plus technique&nbsp;: RSSI, DSI, architectes SI. À l'atelier 2, la direction intervient <b>au minimum lors de la dernière étape</b> pour valider les couples retenus&nbsp;; aux ateliers 1 et 5, elle est pleinement présente."},
{id:"E57", ch:9, d:3, q:"Quelle est la seule donnée de sortie de l'atelier 4&nbsp;?", o:["Les scénarios opérationnels et leur évaluation en vraisemblance","Les scénarios stratégiques et leur gravité","La cartographie de l'écosystème","Le plan de traitement du risque"], a:[0], e:"C'est l'atelier au livrable le plus resserré. À comparer avec l'atelier 1, qui en produit <b>quatre</b>&nbsp;: éléments de cadrage, périmètre métier et technique, événements redoutés et gravité, socle de sécurité."},
{id:"E58", ch:9, d:2, q:"Que reçoit l'atelier 1 <b>en entrée</b>&nbsp;?", o:["Les résultats d'une précédente analyse de risque, si disponibles — rien d'autre n'est requis","Le socle de sécurité de l'organisation","La cartographie du système d'information","La politique de sécurité validée par la direction"], a:[0], e:"C'est ce qui permet à l'analyse de risque de <b>partir de zéro</b>, contrairement à l'audit qui exige un référentiel préexistant. Le socle de sécurité n'est pas une entrée&nbsp;: il est <b>construit</b> par l'activité 1-4."},

/* ---- Ch. 10 : vocabulaire et pièges ---- */
{id:"E59", ch:10, d:2, q:"Gravité et vraisemblance sont déterminées dans quels ateliers&nbsp;?", o:["Gravité à l'atelier 1, vraisemblance à l'atelier 4","Les deux à l'atelier 1","Les deux à l'atelier 4","Gravité à l'atelier 4, vraisemblance à l'atelier 1"], a:[0], e:"C'est la confusion la plus coûteuse de toute la méthode, parce qu'elle fausse la lecture de l'enchaînement. Retenir&nbsp;: la <b>gravité</b> se cote sur ce qu'on <b>perd</b> (donc tôt, avec les métiers)&nbsp;; la <b>vraisemblance</b> sur ce que l'attaquant <b>doit franchir</b> (donc tard, avec les techniciens)."},
{id:"E60", ch:10, d:2, q:"Quelle est la différence entre un <b>scénario stratégique</b> et un <b>scénario opérationnel</b>&nbsp;?", o:["Le stratégique décrit le chemin d'attaque de haut niveau via l'écosystème ; l'opérationnel décrit le mode opératoire technique sur les biens supports","Le stratégique concerne la direction, l'opérationnel les équipes","Le stratégique est long terme, l'opérationnel court terme","Le stratégique est qualitatif, l'opérationnel est quantitatif"], a:[0], e:"Le stratégique répond à «&nbsp;<b>par où</b>&nbsp;», l'opérationnel à «&nbsp;<b>comment</b>&nbsp;». Le premier est coté en <b>gravité</b> (héritée de l'atelier 1), le second en <b>vraisemblance</b>."},
{id:"E61", ch:10, d:2, q:"Que désigne l'<b>objet de l'étude</b>&nbsp;?", o:["Le périmètre retenu pour l'analyse : ce que l'on étudie, avec ses missions et son environnement","La source de risque principale","Le bien support le plus critique","Le livrable final remis à la direction"], a:[0], e:"Le définir est l'<b>activité 1-1</b>. Un objet d'étude mal délimité produit une analyse inexploitable&nbsp;: trop large, elle se dilue&nbsp;; trop étroite, elle rate les chemins d'attaque réels."},
{id:"E62", ch:10, d:3, q:"Quelle est la différence entre <b>bien support</b> et <b>partie prenante</b>&nbsp;?", o:["Le bien support est interne au périmètre de l'étude ; la partie prenante appartient à l'écosystème, hors périmètre","Le bien support est matériel, la partie prenante est humaine","Le bien support est étudié à l'atelier 1, la partie prenante à l'atelier 4","Le bien support porte une valeur métier, la partie prenante porte un risque"], a:[0], e:"C'est la frontière entre l'<b>atelier 1</b> (le dedans) et l'<b>atelier 3</b> (le dehors). Un prestataire d'infogérance est une <b>partie prenante</b>&nbsp;; le serveur qu'il administre, s'il est dans le périmètre, est un <b>bien support</b>."},
{id:"E63", ch:10, d:2, q:"Que traite EBIOS RM des risques <b>accidentels</b> — pannes, inondations, erreurs humaines&nbsp;?", o:["Ils sont renvoyés au socle de sécurité, traité par conformité à l'atelier 1","Ils sont traités comme des scénarios opérationnels à l'atelier 4","Ils sont ignorés par la méthode","Ils font l'objet d'un atelier 6 optionnel"], a:[0], e:"C'est la différence avec <b>EBIOS 2010</b>, qui traitait l'intentionnel <b>et</b> l'accidentel dans la même analyse. EBIOS RM se concentre sur l'intentionnel ciblé et confie le reste au socle — la base de la pyramide."},
{id:"E64", ch:10, d:3, q:"L'analyse EBIOS RM est-elle un exercice individuel&nbsp;?", o:["Non : c'est une démarche par ateliers participatifs réunissant les parties prenantes de l'organisation","Oui : c'est le travail de l'ingénieur sécurité, validé ensuite par la direction","Oui pour les ateliers 1 et 2, non pour les suivants","Cela dépend de la taille de l'organisation"], a:[0], e:"«&nbsp;Vous ne faites <b>pas</b> une analyse de risque enfermé seul dans votre bureau en remplissant des tableaux.&nbsp;» L'analyste doit être <b>facilitateur</b>&nbsp;: son rôle est de canaliser la parole des métiers pour en extraire les vrais événements redoutés."},
{id:"E65", ch:10, d:2, q:"Pourquoi faut-il auditer les <b>mesures existantes</b> avant de préconiser&nbsp;?", o:["Sinon on préconise en fin d'étude des mesures déjà en place depuis des années","Parce que l'ISO 27005 impose un inventaire des contrôles","Parce que la direction exige un chiffrage des mesures existantes","Parce que les mesures existantes servent à coter la gravité"], a:[0], e:"«&nbsp;L'analyse de risque doit toujours partir de l'<b>état réel existant</b>.&nbsp;» C'est l'objet de l'<b>activité 1-4</b>, le socle de sécurité — et c'est aussi ce qui rend l'atelier 1 si long."},
{id:"E66", ch:10, d:3, q:"Que signifie la <b>démarche descendante</b> (<i>top-down</i>) d'EBIOS RM&nbsp;?", o:["On part des objectifs stratégiques de l'attaquant pour descendre vers la technique","On part de la direction générale pour descendre vers les opérationnels","On part des vulnérabilités techniques pour remonter vers les risques métier","On part de la norme pour descendre vers les mesures"], a:[0], e:"C'est l'inverse d'<b>EBIOS 2010</b>, qui était <b>ascendante</b>&nbsp;: elle partait des briques techniques. La démarche descendante évite de noyer l'analyse sous des vulnérabilités sans lien avec un objectif d'attaque crédible."},

/* ---- Ch. 11 : le contexte de la méthode (apports du cours) ---- */
{id:"E67", ch:11, d:2, q:"En quelle année et à la demande de quel organisme la première version d'EBIOS a-t-elle été créée&nbsp;?", o:["En 1995, à la demande de la DCSSI — qui deviendra l'ANSSI en 2009","En 2004, à la demande de l'ANSSI","En 2010, à la demande du Club EBIOS","En 1987, à la demande de la CCTA britannique"], a:[0], e:"La même année, le <b>CLUSIF</b> créait la méthode concurrente <b>MEHARI</b>. Les quatre versions&nbsp;: <b>1995</b> (création) · <b>2004</b> (essor d'Internet) · <b>2010</b> (virtualisation et cloud, 5 modules) · <b>2018</b> (EBIOS Risk Manager, 5 ateliers agiles)."},
{id:"E68", ch:11, d:2, q:"Quelles deux méthodes françaises concurrentes sont nées la <b>même année</b>, et laquelle vient du CLUSIF&nbsp;?", o:["EBIOS et MEHARI, en 1995 — MEHARI vient du CLUSIF","EBIOS et OCTAVE, en 1999 — OCTAVE vient du CLUSIF","MEHARI et CRAMM, en 1987 — MEHARI vient du CLUSIF","EBIOS et Cyber-PHA, en 2010 — Cyber-PHA vient du CLUSIF"], a:[0], e:"MEHARI est privilégiée par les <b>administrations, les collectivités et la Défense / DGA</b>&nbsp;; EBIOS vise le secteur privé, les <b>OIV</b> et les grandes entreprises. Les deux sont françaises, nées en <b>1995</b>."},
{id:"E69", ch:11, d:1, q:"Quelle méthode est présentée comme «&nbsp;l'ancêtre britannique de la suite ISO 27000&nbsp;»&nbsp;?", o:["CRAMM / BS 7799, 1987","OCTAVE, 1999","NIST SP 800-30, 2002","MEHARI, 1995"], a:[0], e:"Le panorama chronologique&nbsp;: <b>CRAMM 1987</b> (Royaume-Uni) · <b>EBIOS et MEHARI 1995</b> (France) · <b>OCTAVE 1999</b> (CERT/SEI, États-Unis) · <b>NIST SP 800-30 2002</b> · <b>Cyber-PHA</b> pour l'industriel, adossé à la CEI 62443."},
{id:"E70", ch:11, d:2, q:"À quel domaine la méthode <b>Cyber-PHA</b> est-elle dédiée, et à quelle norme est-elle adossée&nbsp;?", o:["Aux systèmes industriels — OT, SCADA, automates — et elle est adossée à la CEI 62443","Aux systèmes fédéraux américains, adossée au NIST CSF","Aux données personnelles, adossée au RGPD","Aux systèmes embarqués automobiles, adossée à l'ISO 21434"], a:[0], e:"C'est aussi l'une des méthodes à coupler avec EBIOS RM pour traiter la <b>sûreté</b> (<i>safety</i>), avec l'<b>AMDEC</b>&nbsp;: EBIOS RM ne traite que la <b>sécurité</b>, c'est-à-dire l'intentionnel malveillant."},
{id:"E71", ch:11, d:1, q:"Quel outil labellisé est utilisé pour les travaux pratiques du module&nbsp;?", o:["Agile Risk Manager, édité par AllForTech / Olfeo","Egerie Risk Manager","RSA Archer","Famic, d'Airbus Defence and Space"], a:[0], e:"Décrit en cours comme «&nbsp;de loin l'un des meilleurs du marché&nbsp;», en SaaS sur le VPS de l'école. <b>Famic</b> est réservé aux filières spatiales et défense&nbsp;; <b>RSA Archer</b> est le mastodonte américain du GRC, «&nbsp;hors de prix&nbsp;»&nbsp;; <b>Ermes</b> est open source mais dépassé."},
{id:"E72", ch:11, d:3, q:"Quelle métaphore l'enseignant emploie-t-il pour opposer EBIOS 2010 et EBIOS RM&nbsp;?", o:["Le château fort et la princesse : peu importe que les murs tombent, ce qui compte est que le métier survive","Le fort de Vauban et l'emmental de James Reason","La muraille de Chine et ses passages dérobés","Le triangle du feu et son extinction"], a:[0], e:"«&nbsp;Dans EBIOS 2010, on cherchait à défendre <b>les murs du château fort</b> (le SI). Dans EBIOS RM, on se fiche que les murs tombent&nbsp;: ce qui compte, c'est que <b>la princesse</b> — le processus métier vital — survive&nbsp;!&nbsp;» Les autres métaphores appartiennent à la séance sur la défense en profondeur."},
{id:"E73", ch:11, d:2, q:"Quel cas réel illustre la stratégie de <b>refus / évitement</b> du risque&nbsp;?", o:["Rabobank, qui a fermé sa filiale belge et revendu son portefeuille clients","OVHcloud, qui héberge les serveurs de ses clients","Target, compromis par son prestataire de climatisation","Sony Pictures, dont les courriels ont fuité"], a:[0], e:"Le droit financier belge étant devenu trop complexe et risqué, la banque a <b>supprimé l'activité</b> pour supprimer le risque. <b>OVHcloud</b> illustre le <b>transfert</b>&nbsp;; <b>Target</b> illustre la chaîne d'approvisionnement&nbsp;; <b>Sony</b> illustre l'impact <b>réputationnel</b>."},
{id:"E74", ch:11, d:2, q:"Que veut illustrer l'analogie de la <b>plaque d'égout ronde</b>&nbsp;?", o:["Le refus du risque par conception : une plaque ronde ne peut mathématiquement jamais tomber dans son trou","La réduction du risque par ajout de contre-mesures","Le transfert du risque vers le fabricant","L'acceptation d'un risque résiduel jugé tolérable"], a:[0], e:"Les plaques carrées, insérées en diagonale, pouvaient glisser dans le trou. Passer au rond <b>supprime le risque à la source</b> plutôt que de le réduire ou de le surveiller — c'est la logique du refus, appliquée dès la conception."},
{id:"E75", ch:11, d:3, q:"Que démontre l'anecdote de l'étudiante envoyée chez <b>Thales</b>&nbsp;?", o:["Qu'une analyse de risque peut repartir de zéro là où un audit aurait été bloqué faute de référentiel","Que le départ d'un RSSI invalide une certification ISO 27001","Qu'il faut toujours auditer avant d'analyser","Que l'analyse de risque exige un référentiel préexistant"], a:[0], e:"Le RSSI venait de démissionner&nbsp;: «&nbsp;la mémoire vivante du projet avait disparu&nbsp;». Un <b>audit</b> n'aurait rien pu faire — il compare la réalité à un <b>document</b>. L'<b>analyse de risque</b> a pu reconstituer le panorama par <b>ateliers</b> avec les métiers et les architectes."},

/* ---- Compléments : impacts et parties prenantes ---- */
{id:"E76", ch:1, d:2, q:"Quelles sont les <b>quatre familles d'impacts</b> sur lesquelles se cote la gravité&nbsp;?", o:["Fonctionnel, financier, réputationnel, juridique","Technique, organisationnel, humain, physique","Disponibilité, intégrité, confidentialité, preuve","Immédiat, court terme, moyen terme, long terme"], a:[0], e:"L'impact <b>fonctionnel</b> est l'interruption du processus métier&nbsp;; le <b>financier</b> couvre la perte de chiffre d'affaires et la rançon&nbsp;; le <b>réputationnel</b> est illustré par <b>Ashley Madison</b> et <b>Sony Pictures</b>&nbsp;; le <b>juridique</b> par les amendes CNIL, jusqu'à <b>4&nbsp;% du chiffre d'affaires mondial</b>. Ne pas confondre avec <b>DICP</b> — disponibilité, intégrité, confidentialité, preuve : ce sont les <b>critères de sécurité</b> sur lesquels se formule un événement redouté, pas les familles d&#39;impacts sur lesquelles on le cote."},
{id:"E77", ch:1, d:2, q:"Quels cas illustrent l'impact <b>réputationnel</b> dans le cours&nbsp;?", o:["Ashley Madison (2015) et Sony Pictures (2014)","Target et SolarWinds","Rabobank et OVHcloud","Stuxnet et Natanz"], a:[0], e:"<b>Ashley Madison</b>&nbsp;: la base d'un site de rencontres extraconjugales publiée en clair. <b>Sony Pictures</b>&nbsp;: fuite de courriels internes de dirigeants et de scénarios non sortis. <b>Target</b> et <b>SolarWinds</b> illustrent, eux, la <b>chaîne d'approvisionnement</b>."},
{id:"E78", ch:6, d:1, q:"Quelles sont les <b>trois catégories de parties prenantes</b> analysées à l'atelier 3&nbsp;?", o:["Les clients, les partenaires, les fournisseurs et sous-traitants","Les actionnaires, les salariés, les clients","Les métiers, la DSI, la direction générale","Les autorités, les assureurs, les prestataires"], a:[0], e:"La troisième est «&nbsp;le <b>vecteur d'attaque le plus redoutable aujourd'hui</b>&nbsp;»&nbsp;: l'assaillant cible un petit sous-traitant mal sécurisé pour rebondir vers le donneur d'ordre. Exemples&nbsp;: le prestataire de climatisation chez <b>Target</b>, et <b>SolarWinds</b>."},
{id:"E79", ch:6, d:2, q:"Pourquoi les <b>fournisseurs et sous-traitants</b> sont-ils présentés comme le vecteur le plus redoutable&nbsp;?", o:["Parce que l'assaillant cible le maillon le plus faible de la chaîne pour rebondir vers le donneur d'ordre","Parce qu'ils représentent la majorité des dépenses informatiques","Parce qu'ils sont rarement couverts par une assurance","Parce que le RGPD leur transfère la responsabilité du traitement"], a:[0], e:"C'est la justification directe du <b>fondement 4</b> — la prise en compte de l'écosystème&nbsp;: «&nbsp;de plus en plus de modes opératoires exploitent les <b>maillons les plus vulnérables</b> de cet écosystème pour atteindre leur objectif&nbsp;»."},
{id:"E80", ch:1, d:3, q:"D'où vient la modélisation mathématique du risque&nbsp;?", o:["De Christiaan Huygens (1659), formalisée par Daniel Bernoulli (1738) : le risque comme espérance mathématique du dommage","De Blaise Pascal et Pierre de Fermat, en 1654","De Thomas Bayes, en 1763","D'Andreï Kolmogorov, en 1933"], a:[0], e:"Le risque y est défini comme «&nbsp;la valeur moyenne des conséquences d'événements affectés à leur probabilité d'occurrence&nbsp;». C'est la justification théorique du produit <b>gravité × vraisemblance</b>."},
{id:"E81", ch:1, d:2, q:"Dans l'exemple du <b>conducteur et des platanes</b>, de quoi dépend la <b>gravité</b>&nbsp;?", o:["De la vitesse du véhicule, de la taille de l'arbre et de la valeur de la voiture","De la configuration des lieux et de l'état du conducteur","Des conditions météo et de la présence de glissières","Du nombre d'arbres au bord de la route"], a:[0], e:"Les trois autres propositions relèvent toutes de la <b>vraisemblance</b>&nbsp;: configuration des lieux, état du conducteur, conditions de chaussée, mesures préventives. La gravité porte sur <b>ce que l'on perd</b>&nbsp;; la vraisemblance sur <b>la probabilité que ça arrive</b>."},
{id:"E82", ch:11, d:2, q:"Quelles familles de risques l'<b>ISO 31000</b> couvre-t-elle, selon les exemples du cours&nbsp;?", o:["Le financier (dette grecque), l'industriel (microfissures EDF) et le médical (vaccination)","Uniquement le risque numérique et le risque industriel","Le risque cyber, le risque juridique et le risque de marché","Le risque opérationnel, le risque de crédit et le risque de liquidité"], a:[0], e:"Chacun se décline en danger / risque / dommage. Le cas <b>industriel</b> est le plus parlant&nbsp;: les <b>microfissures</b> sont le danger, <b>décider d'exploiter la centrale sous pression</b> est le risque, la <b>rupture de confinement</b> le dommage. Tant que la centrale est à l'arrêt, le risque est nul."},
{id:"E83", ch:10, d:3, q:"Pourquoi l'<b>IGI 1300</b> n'entre-t-elle pas dans le socle de sécurité&nbsp;?", o:["Parce qu'elle s'impose aux personnes physiques accréditées et aux locaux classifiés, non au système d'information","Parce qu'elle est classifiée et donc non communicable","Parce qu'elle a été abrogée en 2021","Parce qu'elle ne concerne que les OIV"], a:[0], e:"Le critère de tri&nbsp;: le socle rassemble les référentiels <b>applicables au SI</b>. L'anecdote de l'habilitation le rend concret&nbsp;: «&nbsp;toute divulgation, <b>même par négligence</b>, est punie de <b>400 000 euros d'amende et de 20 ans de réclusion</b>&nbsp;» — c'est une pression pénale sur <b>l'individu</b>, pas une règle de gouvernance du SI."},

/* ---- Ch. 12 : le support MethodoSecu2 — commandements, Flash, risque IA ---- */
{id:"E84", ch:12, d:2, q:"Selon le <b>premier commandement</b>, EBIOS RM traite-t-elle les risques non délibérés&nbsp;?", o:["Oui : elle les gère, mais sans les modéliser en scénarios — l'analyse par conformité identifie des écarts","Non : elle ne traite que les attaques intentionnelles ciblées","Oui, en les modélisant comme des scénarios opérationnels particuliers","Non, sauf si l'organisation est un opérateur d'importance vitale"], a:[0], e:"Nuance importante&nbsp;: dire «&nbsp;EBIOS RM ignore l'accidentel&nbsp;» est <b>trop fort</b>. Elle permet de gérer <b>tous les risques numériques</b> — attaques ciblées, accidents, non humains — mais les non délibérés passent par le <b>socle</b> et se traduisent en <b>écarts</b>, pas en scénarios."},
{id:"E85", ch:12, d:2, q:"Selon le <b>cinquième commandement</b>, sur quoi s'évaluent les ressources et la motivation&nbsp;?", o:["Sur le couple source de risque / objectif visé, et non sur la source seule","Sur la source de risque uniquement","Sur l'objectif visé uniquement","Sur la partie prenante concernée"], a:[0], e:"Et la suite du commandement&nbsp;: le <b>niveau de pertinence</b> établi à l'atelier 2 «&nbsp;peut être réutilisé et influer sur l'estimation d'un <b>scénario opérationnel</b>&nbsp;» — donc sur la vraisemblance de l'atelier 4."},
{id:"E86", ch:12, d:2, q:"Que dit le <b>sixième commandement</b> à propos des parties prenantes&nbsp;?", o:["Il paraît illusoire de considérer qu'il n'existe pas de partie prenante : cela voudrait dire un projet sans aucun écosystème","Qu'il faut se limiter à trois parties prenantes maximum","Que seules les parties prenantes contractualisées comptent","Que les parties prenantes relèvent de l'atelier 2, pas de l'atelier 3"], a:[0], e:"Leur création «&nbsp;permet d'avoir la possibilité de créer des <b>chemins d'attaque distincts</b> dans les scénarios stratégiques&nbsp;». C'est la justification opérationnelle du <b>fondement 4</b>, la prise en compte de l'écosystème."},
{id:"E87", ch:12, d:2, q:"Quels sont les <b>quatre critères</b> de cotation de la menace des parties prenantes&nbsp;?", o:["Dépendance, pénétration, maturité cyber, confiance","Gravité, vraisemblance, exposition, criticité","Motivation, ressources, activité, pertinence","Disponibilité, intégrité, confidentialité, preuve"], a:[0], e:"Septième commandement&nbsp;: on recherche une <b>évaluation relative</b> de la menace, afin d'identifier les parties prenantes <b>les plus menaçantes</b>. Les critères et échelles proposés «&nbsp;doivent être adaptés&nbsp;» — ils servent surtout à <b>se poser les bonnes questions</b>."},
{id:"E88", ch:12, d:3, q:"D'où proviennent les <b>mesures de traitement</b> de l'atelier 5, selon le dixième commandement&nbsp;?", o:["De la réflexion de chaque atelier — et non pas uniquement de l'atelier 3 ou 4","Uniquement des ateliers 3 et 4, qui produisent les scénarios","Uniquement de l'atelier 5, qui les définit de zéro","Du socle de sécurité de l'atelier 1 exclusivement"], a:[0], e:"Les mesures <b>ne naissent pas</b> à l'atelier 5&nbsp;: elles y sont <b>consolidées</b>. L'atelier 3 produit déjà des mesures pour l'écosystème, l'atelier 1 identifie les écarts au socle — tout cela remonte à l'atelier 5."},
{id:"E89", ch:12, d:1, q:"Quel est l'objectif de l'<b>approche « Flash »</b>&nbsp;?", o:["Réaliser l'analyse de risques en mobilisant les acteurs pendant 2 à 3 heures","Automatiser l'analyse de risques à l'aide d'un outil labellisé","Réaliser une analyse en une journée complète avec tous les métiers","Produire une analyse conforme sans réunir de parties prenantes"], a:[0], e:"C'est la réponse à la critique d'EBIOS RM en petite structure&nbsp;: on ne renonce pas à la méthode, on en <b>comprime le format</b>. Les bénéfices annoncés&nbsp;: <b>adhésion du métier</b>, identification des <b>risques les plus importants</b>, <b>priorisation</b> des mesures."},
{id:"E90", ch:12, d:2, q:"Quel principe de l'approche Flash porte sur le <b>niveau de détail</b>&nbsp;?", o:["Rester à un niveau d'analyse adapté en limitant le nombre de scénarios, sans se noyer dans les détails ni se focaliser sur une technique d'attaque","Détailler systématiquement la kill chain de chaque scénario","Se limiter à l'atelier 1 et à l'atelier 5","Ne retenir que les risques de gravité G4"], a:[0], e:"Les trois autres principes&nbsp;: confier l'atelier à un <b>sachant</b> maîtrisant méthode, objet et contexte&nbsp;; <b>exploiter les connaissances capitalisées</b> sur des projets similaires&nbsp;; animer de façon <b>collaborative</b> à partir d'un <b>schéma de principe</b> et de <b>fiches</b>."},
{id:"E91", ch:12, d:1, q:"Quelles sont les <b>trois familles de risques liés à l'IA</b>&nbsp;?", o:["L'IA comme cible ou vecteur d'attaque · les risques intrinsèques · les risques causés à des tiers","Technique, organisationnel, juridique","Confidentialité, intégrité, disponibilité","Conception, entraînement, exploitation"], a:[0], e:"Et le constat qui les accompagne&nbsp;: «&nbsp;<b>aucune méthode unique ne permet aujourd'hui de couvrir correctement ces trois familles</b>&nbsp;». C'est le fil conducteur de toute la partie 3 du support."},
{id:"E92", ch:12, d:2, q:"Pourquoi EBIOS RM est-elle <b>inapplicable</b> aux risques intrinsèques de l'IA&nbsp;?", o:["Parce qu'elle repose sur le couple source de risque / objectif visé : sans attaquant, l'atelier 2 devient inapplicable","Parce qu'elle ne sait pas coter la gravité d'un préjudice algorithmique","Parce qu'elle exige un socle de sécurité que l'IA ne possède pas","Parce qu'elle est réservée aux systèmes d'information classiques"], a:[0], e:"«&nbsp;EBIOS <b>ne comporte pas de notion d'erreur intrinsèque</b> (non intentionnelle) d'un système.&nbsp;» C'est exactement la même limite que celle qui lui fait exclure la <b>sûreté</b> (<i>safety</i>)&nbsp;: pas d'attaquant, pas de scénario."},
{id:"E93", ch:12, d:2, q:"Quels risques relèvent de la <b>famille 2</b>, les risques intrinsèques&nbsp;?", o:["Hallucinations, biais, dérive du modèle, opacité, sur-confiance de l'utilisateur","Empoisonnement des données d'entraînement et prompt injection","Discrimination et atteinte aux droits fondamentaux","Vol de modèle et compromission de la chaîne d'approvisionnement"], a:[0], e:"L'empoisonnement, la <i>prompt injection</i>, le vol de modèle et la compromission de la chaîne d'approvisionnement relèvent de la <b>famille 1</b> — l'IA comme cible ou vecteur&nbsp;; la discrimination et l'atteinte aux droits fondamentaux de la <b>famille 3</b> — les préjudices causés à des tiers. La famille 2 se caractérise par l'<b>absence d'attaquant</b>."},
{id:"E94", ch:12, d:2, q:"Comment la question se <b>retourne-t-elle</b> dans la famille 3&nbsp;?", o:["On ne demande plus « quel préjudice subit l'organisation ? » mais « quel préjudice l'organisation fait-elle subir à d'autres ? »","On ne demande plus « qui attaque ? » mais « comment ? »","On ne demande plus « que protéger ? » mais « avec quel budget ? »","On ne demande plus « quelle gravité ? » mais « quelle vraisemblance ? »"], a:[0], e:"C'est la même inversion que celle de <b>HUDERIA</b>. Le support conclut&nbsp;: «&nbsp;ce domaine <b>dépasse le périmètre traditionnel de la SSI</b>&nbsp;» et nécessite une approche <b>juridique, éthique et sociétale</b>."},
{id:"E95", ch:12, d:2, q:"Quelle norme IA joue, pour l'IA, le rôle que l'<b>ISO 27001</b> joue pour la cybersécurité&nbsp;?", o:["L'ISO/IEC 42001, qui définit le système de management de l'IA (AIMS)","L'ISO/IEC 23894, qui gère les risques liés à l'IA","L'ISO/IEC 42005, qui évalue les impacts sur les tiers","Le NIST AI RMF"], a:[0], e:"«&nbsp;L'ISO 42001 joue pour l'IA un rôle comparable à celui de l'ISO 27001 pour la cybersécurité&nbsp;: <b>mettre sous contrôle</b> l'utilisation de l'IA dans l'organisation.&nbsp;» Elle impose d'identifier et de traiter les risques, <b>mais ne prescrit aucune méthode</b> d'analyse."},
{id:"E96", ch:12, d:2, q:"En quoi l'<b>ISO/IEC 23894</b> se distingue-t-elle de l'ISO 27005&nbsp;?", o:["Elle ne se limite pas aux risques de sécurité : elle couvre aussi les risques techniques, opérationnels, éthiques, sociétaux et réglementaires","Elle est certifiable, contrairement à l'ISO 27005","Elle s'applique uniquement aux systèmes d'IA générative","Elle prescrit une méthode d'analyse unique et obligatoire"], a:[0], e:"Ses cinq principes&nbsp;: approche fondée sur le risque · <b>gestion du cycle de vie</b> de l'IA · surveillance continue · amélioration continue · <b>gouvernance adaptée au contexte métier</b>."},
{id:"E97", ch:12, d:3, q:"Quelle est la question centrale de l'<b>ISO/IEC 42005</b>&nbsp;?", o:["« Qui pourrait être affecté par cette IA, et comment ? »","« Quel est le niveau de maturité de notre gouvernance IA ? »","« Quelles sources de risque visent notre modèle ? »","« Le modèle est-il conforme à l'AI Act ? »"], a:[0], e:"Sa démarche en cinq étapes&nbsp;: identifier les <b>parties prenantes</b> · identifier les <b>impacts possibles</b> · évaluer leur <b>gravité</b> · définir des <b>mesures de réduction</b> · <b>documenter les arbitrages</b>. Elle se rapproche d'une <b>AIPD</b> plus que d'une analyse de risque cyber."},
{id:"E98", ch:12, d:2, q:"D'où vient la méthodologie <b>HUDERIA</b>, et quel est son statut&nbsp;?", o:["Du Conseil de l'Europe (2024), complétée par le modèle COBRA (2026) — elle est non contraignante","De l'ANSSI, en complément d'EBIOS RM — elle est obligatoire pour les OIV","De la Commission européenne, dans le cadre de l'AI Act — elle est contraignante","Du NIST, en complément du AI RMF — elle est volontaire"], a:[0], e:"Elle soutient la <b>Convention-cadre sur l'IA</b>. Ses quatre temps&nbsp;: analyse contextuelle et <b>triage</b> · <b>parties prenantes</b> et corroboration · évaluation d'impact par <b>gravité, portée, réversibilité</b> · atténuation et <b>voies de recours</b>."},
{id:"E99", ch:12, d:3, q:"Quelle <b>inversion de perspective</b> HUDERIA opère-t-elle par rapport à EBIOS RM&nbsp;?", o:["EBIOS RM protège les valeurs métier de l'organisation ; HUDERIA évalue le préjudice que l'organisation peut faire subir aux droits humains, à la démocratie et à l'État de droit","EBIOS RM est qualitative, HUDERIA est quantitative","EBIOS RM vise le court terme, HUDERIA le long terme","EBIOS RM s'applique au privé, HUDERIA au secteur public"], a:[0], e:"C'est la phrase de synthèse du support, et elle reprend exactement l'inversion de la <b>famille 3</b>. Trois caractéristiques transverses&nbsp;: <b>réexamen itératif</b>, approche <b>socio-technique</b>, <b>documentation continue</b>."},
{id:"E100", ch:12, d:3, q:"Quelles limites le support relève-t-il pour HUDERIA en <b>petite organisation</b>&nbsp;?", o:["Elle est écrite pour des acteurs étatiques et elle est énergivore : l'engagement des parties prenantes est hors de portée","Elle est payante et son référentiel n'est pas public","Elle exige une certification préalable ISO 42001","Elle n'est disponible qu'en anglais"], a:[0], e:"Ce qu'apporterait une déclinaison&nbsp;: un <b>triage d'une page</b> — parcours complet, allégé, ou aucun — et des <b>profils sectoriels</b> désignant les droits en jeu. C'est, pour HUDERIA, l'équivalent de ce qu'est l'<b>approche Flash</b> pour EBIOS RM."},

/* ---------- 13. Les cas pratiques du support (exercices 4 a 8, exemple 2) ---- */
{id:"E102", ch:13, d:3, q:"Dans le cas du collégien qui sature la messagerie du collège, quel est l'<b>objectif visé</b>&nbsp;?", o:["Se venger du collège","Rendre les échanges impossibles pendant plusieurs jours","Saturer le serveur de messagerie","Nuire à l'image de l'établissement auprès des familles"], a:[0], e:"L'objectif visé appartient à l'<b>attaquant</b>&nbsp;: c'est ce que <i>lui</i> veut obtenir. Les autres formulations décrivent ce que <b>le collège</b> subit — l'indisponibilité est l'<b>événement redouté</b>, la saturation le <b>mode opératoire</b>, l'atteinte à l'image un <b>impact</b>. Quatre notions distinctes sur une seule phrase de presse."},
{id:"E103", ch:13, d:2, q:"Toujours dans le cas du collégien&nbsp;: quelle est la <b>valeur métier</b>, et quel est le <b>bien support</b>&nbsp;?", o:["Valeur métier : échanger des informations avec les élèves et les familles. Bien support : le service de messagerie","Valeur métier : le service de messagerie. Bien support : les serveurs du collège","Valeur métier : la réputation du collège. Bien support : les courriels","Valeur métier : les 40 000 courriels. Bien support : le réseau"], a:[0], e:"La valeur métier est un <b>processus ou une information</b> — quelque chose que l'établissement <b>fait</b>. Le bien support est le <b>composant concret</b> qui le porte. Confondre les deux revient à dire que le métier d'un collège est d'avoir des serveurs."},
{id:"E104", ch:13, d:3, q:"Dans le cas Marriott, la brèche vient de la base de <b>Starwood</b>, filiale rachetée. Qu'est-ce que cela illustre&nbsp;?", o:["Que le risque est entré par l'écosystème — d'où l'atelier 3 et la cotation des parties prenantes","Que le socle de sécurité de l'atelier 1 était incomplet","Que la gravité avait été sous-cotée à l'atelier 1","Que les scénarios opérationnels de l'atelier 4 n'avaient pas été élaborés"], a:[0], e:"Une entité rachetée, un prestataire, un partenaire sont des <b>parties prenantes</b>&nbsp;: forte dépendance, forte pénétration, maturité souvent inconnue. C'est le cas d'école de l'<b>atelier 3</b>, et l'argument le plus concret pour justifier son existence."},
{id:"E105", ch:13, d:3, q:"Marriott indique que les numéros de carte étaient <b>chiffrés</b>, sans exclure que les éléments de déchiffrement aient été compromis. Comment traiter cette information en analyse de risque&nbsp;?", o:["La mesure ne réduit le risque que si son hypothèse tient : avec les clés compromises, l'événement redouté reste entier","Le chiffrement étant une mesure du socle, le risque résiduel est nul","C'est un impact juridique, pas un point d'analyse","Cela relève de l'atelier 4, pas de l'atelier 1"], a:[0], e:"C'est le réflexe à avoir sur <b>toute mesure déclarée</b>&nbsp;: une mesure vaut par son <b>hypothèse</b>. Chiffrer protège tant que la clé est protégée — sinon on a déplacé le problème, pas traité le risque. Le risque résiduel se <b>réévalue</b>, il ne se décrète pas."},
{id:"E106", ch:13, d:2, q:"Dans le cas Pathé — 19,2 M€ détournés par fraude au président — quel est le <b>bien support</b>&nbsp;?", o:["Le collaborateur habilité à ordonner les virements, et la procédure d'autorisation","Le système bancaire en ligne de l'entreprise","La messagerie électronique de la direction","Le compte tiers ouvert à Dubaï"], a:[0], e:"Il n'y a <b>aucune vulnérabilité informatique</b> dans ce scénario. Le fondement le dit&nbsp;: les biens supports peuvent être numériques, physiques <b>ou organisationnels, y compris des personnes</b>. La mesure attendue est une <b>procédure</b> — double validation, rappel sur un canal indépendant — pas un équipement."},
{id:"E107", ch:13, d:3, q:"Dans le cas Qantas, les données sont volées en <b>juin</b> et publiées en <b>octobre</b>, après expiration de l'échéance de rançon. Qu'en tirer&nbsp;?", o:["L'événement redouté peut se réaliser longtemps après l'incident technique : une analyse qui s'arrête à l'intrusion rate l'essentiel","L'événement redouté s'est produit en juin, la publication n'est qu'un impact secondaire","Le délai prouve que la vraisemblance était faible","Il s'agit de deux risques distincts, à coter séparément"], a:[0], e:"L'<b>événement redouté</b> est la <b>divulgation</b>, pas l'intrusion. L'intrusion n'est qu'un maillon du chemin d'attaque. C'est aussi ce qui distingue l'<b>extorsion sans chiffrement</b> du rançongiciel classique&nbsp;: le levier est la <b>publication</b>, pas le blocage."},
{id:"E108", ch:13, d:2, q:"Dans le cas Qantas, les données volées se trouvaient dans une base <b>Salesforce</b>. Quelle conséquence en analyse&nbsp;?", o:["Le service SaaS est un bien support, et son fournisseur une partie prenante à coter à l'atelier 3","Le risque relève du fournisseur : il sort du périmètre de l'étude","Le SaaS n'est pas un bien support puisqu'il n'est pas hébergé par l'organisme","Il faut le traiter comme un bien support organisationnel, pas numérique"], a:[0], e:"Externaliser un traitement n'externalise pas le risque&nbsp;: la <b>valeur métier reste la vôtre</b>. Le fournisseur devient une partie prenante à forte <b>dépendance</b> et forte <b>pénétration</b> — donc typiquement une <b>partie prenante critique</b>."},
{id:"E109", ch:13, d:3, q:"Le cas Nintendo repose sur une revendication <b>non confirmée</b> («&nbsp;si elle est authentique&nbsp;»). Peut-on l'utiliser en analyse de risque&nbsp;?", o:["Oui : on travaille sur des scénarios vraisemblables, pas sur des faits établis","Non : sans confirmation, la vraisemblance ne peut pas être cotée","Non : un scénario non confirmé relève de la réponse à incident","Oui, mais uniquement comme source de risque secondaire à mettre sous surveillance"], a:[0], e:"C'est la différence de nature entre l'<b>analyse de risque</b>, qui est <b>prospective</b>, et la <b>réponse à incident</b>, qui porte sur du <b>constaté</b>. Attendre la confirmation pour analyser reviendrait à n'analyser que ce qui a déjà eu lieu."},
{id:"E110", ch:13, d:2, q:"Laquelle de ces propositions n'est <b>pas</b> une qualité attendue d'une échelle de cotation&nbsp;?", o:["Être la plus fine possible, pour permettre des cotations nuancées","Être discriminante, c'est-à-dire séparer réellement les situations","Être non ambiguë, chaque niveau décrit par des critères observables","Être partagée, validée par le métier et non décrétée par le RSSI"], a:[0], e:"Une échelle <b>trop fine cesse d'être discriminante</b>&nbsp;: personne ne sait défendre l'écart entre un 6 et un 7 sur dix, et tout le monde se replie sur le milieu. C'est la raison des <b>quatre niveaux</b> G1-G4 — et du nombre <b>pair</b>, qui interdit le milieu confortable et force l'arbitrage."},
{id:"E111", ch:13, d:3, q:"PSSI, RGPD, guide d'hygiène ANSSI, annexe A de l'ISO 27001, code de la santé publique, LPM, IGI 1300&nbsp;: lesquels font partie du socle de sécurité&nbsp;?", o:["Cela dépend de l'organisme : le socle se compose des référentiels applicables compte tenu de son secteur et de son statut","Les quatre premiers seulement : les trois derniers sont sectoriels et sortent du socle","Tous, sans condition : le socle est la somme des référentiels existants","Aucun : le socle ne contient que des mesures, pas des référentiels"], a:[0], e:"La réponse attendue n'est pas une liste mais un <b>critère</b>. Le code de la santé publique s'impose à un hôpital, pas à un e-commerçant&nbsp;; la <b>LPM</b> aux <b>OIV</b>&nbsp;; l'<b>IGI 1300</b> dès qu'il y a du secret de la défense nationale. Et le livrable de l'activité 1-4 n'est pas la liste&nbsp;: ce sont les <b>écarts</b> et leur <b>justification</b>."}

];
